import{_ as t,o as a,c as o,az as s}from"./chunks/framework.DXXa9EJF.js";const u=JSON.parse('{"title":"MCP Server","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/index.md","filePath":"mcp/index.md"}'),n={name:"mcp/index.md"};function r(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to “MCP Server”">​</a></h1><p>ImagenHub speaks the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> (MCP), so an AI agent — Claude, or any MCP-compatible client — can browse models and templates, generate images, and read back results by calling tools instead of writing HTTP requests by hand.</p><p>It&#39;s the same product as the <a href="/api/">REST API</a> behind the scenes — the same account, credits, templates, and tasks. MCP just exposes them as agent-callable tools.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to “When to use it”">​</a></h2><table tabindex="0"><thead><tr><th>Use the MCP server when…</th><th>Use the <a href="/api/">REST API</a> when…</th></tr></thead><tbody><tr><td>You want an AI agent to drive ImagenHub conversationally or autonomously</td><td>You&#39;re writing application code that calls ImagenHub directly</td></tr><tr><td>Your client already speaks MCP (Claude Desktop, Claude Code, …)</td><td>You need fine-grained control over each request</td></tr></tbody></table><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to “Endpoint”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://api.imagenhub.ai/mcp/imagenhub</span></span></code></pre></div><p>A single MCP endpoint over Streamable HTTP. Authentication uses your ImagenHub API key — the same key as the REST API. The agent never sees the key; your MCP client holds it and sends it on every call. See <a href="/mcp/connecting">Connecting a Client</a>.</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to “The tools”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>list-templates</code></td><td>Browse the templates available to the account</td></tr><tr><td><code>get-template</code></td><td>Inspect one template&#39;s inputs and prompt variables</td></tr><tr><td><code>list-models</code></td><td>List models and their input schemas</td></tr><tr><td><code>generate-image</code></td><td>Start a generation from a template or model</td></tr><tr><td><code>get-task</code></td><td>Poll a generation for status and output images</td></tr><tr><td><code>list-tasks</code></td><td>Review past generations</td></tr></tbody></table><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to “Typical workflow”">​</a></h2><ol><li><strong>Discover</strong> — <code>list-templates</code> or <code>list-models</code> to see what&#39;s available.</li><li><strong>Inspect</strong> — <code>get-template</code> to see the inputs a template accepts.</li><li><strong>Generate</strong> — <code>generate-image</code>. Generation is asynchronous; it returns a task id with status <code>created</code>.</li><li><strong>Poll</strong> — <code>get-task</code> with that id until status is <code>success</code>, then read the output image URLs. <code>list-tasks</code> reviews earlier runs.</li></ol><p>Each successful generation charges credits to the account, just like the REST API (a <code>sk_test_</code> key connects and runs without charging).</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/mcp/connecting">Connecting a Client</a> — point Claude or another MCP client at the server.</li><li><a href="/mcp/tools">Tool Reference</a> — every tool, its parameters, and what it returns.</li></ul>',15)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
